import{_ as a,c as e,o,ae as i}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"features/notifications.md","filePath":"features/notifications.md"}'),n={name:"features/notifications.md"};function r(s,t,c,h,d,l){return o(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><h2 id="stay-informed-about-important-changes" tabindex="-1">Stay Informed About Important Changes <a class="header-anchor" href="#stay-informed-about-important-changes" aria-label="Permalink to &quot;Stay Informed About Important Changes&quot;">​</a></h2><p>Notifications keep you up to date on significant events related to your podcast — chart appearances, editorial features, PR mentions, competitor activity, trend alerts, and more. Instead of checking every section manually, notifications bring the most important updates to you.</p><p><strong>To access</strong>: Click <strong>Notifications</strong> in the sidebar.</p><h2 id="what-gets-notified" tabindex="-1"><strong>What Gets Notified</strong> <a class="header-anchor" href="#what-gets-notified" aria-label="Permalink to &quot;**What Gets Notified**&quot;">​</a></h2><p>PodSEO sends notifications for events that are likely to require your attention:</p><ul><li><strong>Chart appearances</strong> — When your podcast enters a platform chart</li><li><strong>Editorial features</strong> — When your podcast is added to a curated or editorial list</li><li><strong>PR mentions</strong> — When your podcast is picked up by a new PR or media source</li><li><strong>Pulse alerts</strong> — Trending news and topics relevant to your podcast&#39;s niche</li><li><strong>Competitor activity</strong> — Notable chart, editorial, and PR changes from podcasts you&#39;re tracking</li><li><strong>System updates</strong> — Important changes to your account or PodSEO features</li></ul><h2 id="managing-notifications" tabindex="-1"><strong>Managing Notifications</strong> <a class="header-anchor" href="#managing-notifications" aria-label="Permalink to &quot;**Managing Notifications**&quot;">​</a></h2><p>You can configure which notifications you receive and how you receive them from <strong>Settings → Notifications</strong>. This lets you focus on the signals that matter most to your workflow without being overwhelmed by updates.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>Notifications surface key moments from across PodSEO, including insights from <a href="/features/keyword-strategy.html">Search Visibility</a>, <a href="/features/competitive-analysis.html">Competition</a>, and <a href="/features/pulse.html">Pulse</a>. For a more comprehensive view, visit the <a href="/features/command-center.html">Command Center</a> which aggregates signals, tasks, and insights in one dashboard.</p>',11)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
